import java.util.*;

class Solution {
  public int magnificentSets(int n, int[][] edges) {
    List<Integer>[] graph = new ArrayList[n];
    for (int i = 0; i < n; i++) graph[i] = new ArrayList<>();
    for (int[] edge : edges) {
      int a = edge[0] - 1, b = edge[1] - 1;
      graph[a].add(b);
      graph[b].add(a);
    }
    int[] color = new int[n];
    int answer = 0;
    for (int start = 0; start < n; start++) {
      if (color[start] != 0) continue;
      List<Integer> component = new ArrayList<>();
      ArrayDeque<Integer> queue = new ArrayDeque<>();
      queue.add(start);
      color[start] = 1;
      while (!queue.isEmpty()) {
        int u = queue.remove();
        component.add(u);
        for (int v : graph[u]) {
          if (color[v] == 0) {
            color[v] = -color[u];
            queue.add(v);
          } else if (color[v] == color[u]) return -1;
        }
      }
      int best = 0;
      for (int source : component) best = Math.max(best, levels(source, graph));
      answer += best;
    }
    return answer;
  }

  private int levels(int source, List<Integer>[] graph) {
    int[] distance = new int[graph.length];
    Arrays.fill(distance, -1);
    ArrayDeque<Integer> queue = new ArrayDeque<>();
    queue.add(source);
    distance[source] = 0;
    int maximum = 1;
    while (!queue.isEmpty()) {
      int u = queue.remove();
      for (int v : graph[u])
        if (distance[v] < 0) {
          distance[v] = distance[u] + 1;
          maximum = Math.max(maximum, distance[v] + 1);
          queue.add(v);
        }
    }
    return maximum;
  }
}
